-- MT2009_PLUS_YOHARA_ILUZJA_V1: the elements of the two awakened dungeons (setRaceFlag bits 11-16: 2048 lightning,
-- 16384 wind) as on the pl-wiki ("Zywiol": Beran-Setaou (PB) and the Setaou / Yonghan lightning, Jotun Thrym (PB) and
-- the En-Tai wind; Owsap's AttElec / AttWind agree). GENERATED by tools/yohara_iluzja/gen_yiluzja.py. apply.sh runs it
-- AFTER zywioly_moby.sql, which clears bits 11-16 of every mob it does not list: idempotent.
-- MT2009_PLUS_YOHARA_RASY_V1: then the races (bits 0-10) the data file's RACE fixes (Jotun Thrym: a devil).
SET NAMES utf8mb4;
-- blyskawica: 4280,4281,4282,4283,4284,4285,4286,4287,4288,4289,4290,4410
UPDATE world.mob_proto SET setRaceFlag = ((setRaceFlag + 0) & ~129024) | 2048 WHERE vnum IN (4280,4281,4282,4283,4284,4285,4286,4287,4288,4289,4290,4410);
-- wiatr: 4340,4341,4342,4343,4344,4345,4347,4348,4349,4350,4351,4352,4413
UPDATE world.mob_proto SET setRaceFlag = ((setRaceFlag + 0) & ~129024) | 16384 WHERE vnum IN (4340,4341,4342,4343,4344,4345,4347,4348,4349,4350,4351,4352,4413);
-- no element (the Metins - the wiki gives a Metin none): 8130,8131,8132,8133,8136,8137
UPDATE world.mob_proto SET setRaceFlag = (setRaceFlag + 0) & ~129024 WHERE vnum IN (8130,8131,8132,8133,8136,8137) AND (setRaceFlag + 0) & 129024 <> 0;
-- race DEVIL: 4413
UPDATE world.mob_proto SET setRaceFlag = ((setRaceFlag + 0) & ~2047) | 4 WHERE vnum IN (4413) AND (setRaceFlag + 0) & 2047 <> 4;
